import{_ as o,o as e,c as r,a2 as s}from"./chunks/framework.Desnpdez.js";const g=JSON.parse('{"title":"Compared to other MCP hosts","description":"","frontmatter":{},"headers":[],"relativePath":"reference/host-parity.md","filePath":"reference/host-parity.md"}'),n={name:"reference/host-parity.md"};function d(a,t,i,c,p,l){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="compared-to-other-mcp-hosts" tabindex="-1">Compared to other MCP hosts <a class="header-anchor" href="#compared-to-other-mcp-hosts" aria-label="Permalink to &quot;Compared to other MCP hosts&quot;">​</a></h1><p>MindBehindAI is a <strong>desktop bridge + orchestrator</strong>: it runs <a href="https://github.com/open-webui/mcpo" target="_blank" rel="noreferrer"><strong>mcpo</strong></a> locally, stores your <strong>connections</strong>, and publishes HTTP/OpenAPI URLs for assistants. It is <strong>not</strong> a chat app or IDE.</p><table tabindex="0"><thead><tr><th>Topic</th><th>MindBehindAI</th><th>Typical hosts (VS Code, Cursor, Claude Desktop, …)</th></tr></thead><tbody><tr><td><strong>Chat / LLM UI</strong></td><td>Use an external assistant; copy links or sync Open WebUI</td><td>Often built-in chat</td></tr><tr><td><strong>Connection profiles</strong></td><td>stdio, SSE, streamable HTTP; on/off toggles</td><td>Similar transports; sometimes workspace-bound</td></tr><tr><td><strong>Import / export</strong></td><td><code>mcp.json</code>-style JSON (<code>mcpServers</code> / <code>servers</code>, optional <code>inputs</code>)</td><td>Same family of formats</td></tr><tr><td><strong>Tool visibility</strong></td><td>Per-connection tool list; disabled tools persisted</td><td>Varies by host</td></tr><tr><td><strong>OAuth</strong></td><td>Driven by <strong>mcpo</strong> with your default browser when servers use loopback callbacks</td><td>Webviews or custom flows</td></tr><tr><td><strong>Bridge process</strong></td><td>Bundled <strong>mcpo</strong> plus bundled <strong>Node</strong>, <strong>uv/uvx</strong>, and <strong>CPython</strong> on <code>PATH</code> for stdio tools; <strong>no Docker</strong> for the bridge itself</td><td>Inline adapters or extensions</td></tr><tr><td><strong>Presets</strong></td><td>In-app <strong>Library</strong> (Telekom Telecontext, Microsoft 365, …)</td><td>Marketplace or none</td></tr><tr><td><strong>Policy / trust</strong></td><td>Local app + license</td><td>Org policies, extension stores, etc.</td></tr></tbody></table><p>Use this page when deciding whether MindBehindAI alone covers your workflow or whether you still need another <strong>host</strong> for chat, workspace context, or enterprise controls.</p>',4)])])}const m=o(n,[["render",d]]);export{g as __pageData,m as default};
